TEST_F(SecondaryViewTest, AtomicWrapUsesTheCommonAncestorAndPreservesUnicodeNoBreakControls) {
    init_vector_engine();
    stylesheet("@page { size: 100px 160px; margin: 10px } div, p { margin: 0; font-size: 10px; line-height: 12px; orphans: 1; widows: 1 }");
    const char* neighbors[] = {"A", "\xc2\xa0", "\xe2\x81\xa0", "\xe2\x80\x8d", "\xe2\x80\xaf", "\xe2\x80\x87", "\xe2\x80\x91"};
    for (size_t separated = 0; separated < 2; separated++)
    for (size_t side = 0; side < 2; side++) for (size_t i = 0; i < sizeof(neighbors) / sizeof(neighbors[0]); i++) {
        SCOPED_TRACE(separated);
        SCOPED_TRACE(side);
        SCOPED_TRACE(i);
        StrBuf* label = strbuf_new(); ASSERT_NE(label, nullptr);
        if (side && separated) strbuf_append_char(label, ' ');
        if (!side && i) strbuf_append_char(label, 'A');
        strbuf_append_str(label, neighbors[i]);
        if (side && i) strbuf_append_char(label, 'A');
        if (!side && separated) strbuf_append_char(label, ' ');
        DomElement* body = block(!side ? label->str : nullptr); ASSERT_NE(body, nullptr);
        ASSERT_NE(block(nullptr, "display: none", "span", body), nullptr);
        DomElement* atom = image("width: 80px; height: 10px; white-space: nowrap", body); ASSERT_NE(atom, nullptr);
        ASSERT_NE(block(nullptr, "display: none", "span", body), nullptr);
        DomElement* word = side ? block(label->str, nullptr, "span", body) : body;
        strbuf_free(label); ASSERT_NE(word, nullptr);
        ViewTree* tree = secondary(); PagedLayoutOptions options = paged_layout_options_default(); PagedLayoutDiagnostic diagnostic = {};
        TypesetStatus status = layout_secondary_view(tree, &options, &diagnostic);
        if (i < 2 || separated) {
            ASSERT_EQ(status, TYPESET_OK) << diagnostic.reason;
            LayoutViewNode* text = source_fragment(tree, word->first_child, VIEW_FRAGMENT_BODY, false);
            LayoutViewNode* fragment = source_image_fragment(tree, atom); ASSERT_NE(text, nullptr); ASSERT_NE(fragment, nullptr);
            if (side) EXPECT_GT(text->rect.y, fragment->rect.y);
            else EXPECT_GT(fragment->rect.y, text->rect.y);
            EXPECT_FLOAT_EQ(fragment->rect.x, 10.0f);
        } else {
            // no break fits, so one overfull line keeps both and overflows its end edge (CSS 2.2 §9.4.2).
            ASSERT_EQ(status, TYPESET_OK) << diagnostic.reason;
            LayoutViewNode* text = source_fragment(tree, word->first_child, VIEW_FRAGMENT_BODY, false);
            LayoutViewNode* fragment = source_image_fragment(tree, atom); ASSERT_NE(text, nullptr); ASSERT_NE(fragment, nullptr);
            EXPECT_LT(text->rect.y, fragment->rect.y + fragment->rect.height);
            EXPECT_LT(fragment->rect.y, text->rect.y + text->rect.height);
            if (side) EXPECT_GE(text->rect.x, fragment->rect.x + fragment->rect.width);
            else EXPECT_GT(fragment->rect.x + fragment->rect.width, 90.0f);
        }
        ASSERT_TRUE(view_tree_secondary_release(&doc, tree));
        ASSERT_TRUE(source->DomNode::remove_child(body));
    }
    DomElement* body = block(nullptr); ASSERT_NE(body, nullptr);
    DomElement* nowrap = block(nullptr, "white-space: nowrap", "span", body); ASSERT_NE(nowrap, nullptr);
    DomElement* first = image("width: 50px; height: 10px; white-space: normal", nowrap); ASSERT_NE(first, nullptr);
    DomElement* second = image("width: 50px; height: 10px; white-space: normal", nowrap); ASSERT_NE(second, nullptr);
    ViewTree* tree = secondary(); PagedLayoutOptions options = paged_layout_options_default();
    ASSERT_EQ(layout_secondary_view(tree, &options, nullptr), TYPESET_OK);
    LayoutViewNode* placed[] = {source_image_fragment(tree, first), source_image_fragment(tree, second)};
    ASSERT_NE(placed[0], nullptr); ASSERT_NE(placed[1], nullptr);
    EXPECT_FLOAT_EQ(placed[0]->rect.y, placed[1]->rect.y); EXPECT_FLOAT_EQ(placed[1]->rect.x, 60.0f);
    ASSERT_TRUE(view_tree_secondary_release(&doc, tree));
    ASSERT_TRUE(source->DomNode::remove_child(body));
    // a nowrap wrapper's first child can break against text outside that wrapper.
    body = block("A"); ASSERT_NE(body, nullptr);
    nowrap = block(nullptr, "white-space: nowrap", "span", body); ASSERT_NE(nowrap, nullptr);
    DomElement* atom = image("width: 80px; height: 10px; white-space: normal", nowrap); ASSERT_NE(atom, nullptr);
    tree = secondary(); ASSERT_EQ(layout_secondary_view(tree, &options, nullptr), TYPESET_OK);
    LayoutViewNode* text = source_fragment(tree, body->first_child, VIEW_FRAGMENT_BODY, false);
    LayoutViewNode* fragment = source_image_fragment(tree, atom); ASSERT_NE(text, nullptr); ASSERT_NE(fragment, nullptr);
    EXPECT_GT(fragment->rect.y, text->rect.y); EXPECT_FLOAT_EQ(fragment->rect.x, 10.0f);
}

TEST_F(SecondaryViewTest, PagedHtmlDefaultsShareTheDefaultViewElementTable) {
    init_vector_engine();
    stylesheet("@page { size: 400px 600px; margin: 10px } .plain { white-space: normal }");
    DomElement* heading = block("Title", nullptr, "h1"); ASSERT_NE(heading, nullptr);
    DomElement* paragraph = block(nullptr, nullptr, "p"); ASSERT_NE(paragraph, nullptr);
    DomElement* bold = block("bold", nullptr, "b", paragraph); ASSERT_NE(bold, nullptr);
    DomElement* small = block("small", nullptr, "small", paragraph); ASSERT_NE(small, nullptr);
    DomElement* code = block("code", nullptr, "code", paragraph); ASSERT_NE(code, nullptr);
    DomElement* preformatted = block("a  b", nullptr, "pre"); ASSERT_NE(preformatted, nullptr);
    DomElement* plain = block("a  b", nullptr, "pre"); ASSERT_NE(plain, nullptr); ASSERT_TRUE(plain->set_attribute("class", "plain"));
    DomElement* quote = block("quote", nullptr, "blockquote"); ASSERT_NE(quote, nullptr);
    DomElement* outer = block(nullptr, nullptr, "ul"); ASSERT_NE(outer, nullptr);
    DomElement* item = block("one", nullptr, "li", outer); ASSERT_NE(item, nullptr);
    DomElement* inner = block(nullptr, nullptr, "ul", item); ASSERT_NE(inner, nullptr);
    ASSERT_NE(block("two", nullptr, "li", inner), nullptr);
    DomElement* list = block(nullptr, nullptr, "dl"); ASSERT_NE(list, nullptr);
    DomElement* description = block("description", nullptr, "dd", list); ASSERT_NE(description, nullptr);
    ViewTree* tree = secondary(); PagedLayoutOptions options = paged_layout_options_default(); PagedLayoutDiagnostic diagnostic = {};
    ASSERT_EQ(layout_secondary_view(tree, &options, &diagnostic), TYPESET_OK) << diagnostic.reason;
    // the page flow is the browsing layout, so HTML element defaults are the browsing UA defaults
    LayoutViewNode* title = source_glyph_text(tree, heading->first_child, "Title"); ASSERT_NE(title, nullptr);
    EXPECT_FLOAT_EQ(title->glyph_run->font_size, 32.0f); EXPECT_EQ(title->glyph_run->font_weight, 700);
    EXPECT_EQ(source_glyph_text(tree, bold->first_child, "bold")->glyph_run->font_weight, 700);
    EXPECT_NEAR(source_glyph_text(tree, small->first_child, "small")->glyph_run->font_size, 16.0f * 0.83f, 0.001f);
    // a medium-lineage size switching to monospace scales by 13/16
    LayoutViewNode* mono = source_glyph_text(tree, code->first_child, "code"); ASSERT_NE(mono, nullptr);
    EXPECT_FLOAT_EQ(mono->glyph_run->font_size, 13.0f);
    EXPECT_STREQ(paint_glyph_run_font(mono->glyph_run)->style->family, "monospace");
    // preformatted text keeps both spaces; the author override collapses them
    LayoutViewNode* kept = source_glyph_text(tree, preformatted->first_child, "a  b"); ASSERT_NE(kept, nullptr);
    LayoutViewNode* collapsed = source_glyph_text(tree, plain->first_child, "a b"); ASSERT_NE(collapsed, nullptr);
    EXPECT_GT(kept->rect.width, collapsed->rect.width);
    // margins use the heading's own em, the 40px indents, and nested lists drop their outer margins
    LayoutViewNode* heading_box = source_fragment(tree, heading, VIEW_FRAGMENT_BODY, true); ASSERT_NE(heading_box, nullptr);
    LayoutViewNode* paragraph_box = source_fragment(tree, paragraph, VIEW_FRAGMENT_BODY, true); ASSERT_NE(paragraph_box, nullptr);
    EXPECT_NEAR(paragraph_box->rect.y - (heading_box->rect.y + heading_box->rect.height), 32.0f * 0.67f, 0.01f);
    LayoutViewNode* quote_box = source_fragment(tree, quote, VIEW_FRAGMENT_BODY, true); ASSERT_NE(quote_box, nullptr);
    EXPECT_FLOAT_EQ(quote_box->rect.x, paragraph_box->rect.x + 40.0f);
    LayoutViewNode* description_box = source_fragment(tree, description, VIEW_FRAGMENT_BODY, true); ASSERT_NE(description_box, nullptr);
    EXPECT_FLOAT_EQ(description_box->rect.x, paragraph_box->rect.x + 40.0f);
    LayoutViewNode* outer_box = source_fragment(tree, outer, VIEW_FRAGMENT_BODY, true); ASSERT_NE(outer_box, nullptr);
    LayoutViewNode* inner_box = source_fragment(tree, inner, VIEW_FRAGMENT_BODY, true); ASSERT_NE(inner_box, nullptr);
    EXPECT_FLOAT_EQ(inner_box->rect.x, outer_box->rect.x + 40.0f);
    // the list item's first child is now its generated marker; the text follows it
    DomNode* item_source = item->first_child;
    while (item_source && !item_source->is_text()) item_source = item_source->next_sibling;
    LayoutViewNode* item_text = source_glyph_text(tree, item_source, "one"); ASSERT_NE(item_text, nullptr);
    EXPECT_FLOAT_EQ(inner_box->rect.y, item_text->rect.y + item_text->rect.height);
    // list markers publish as generated boxes of their items: a disc, then a circle one level down
    size_t markers = 0;
    for (LayoutViewNode* occurrence = view_tree_node_state(tree, item, false)->first_occurrence; occurrence; occurrence = occurrence->next_occurrence)
        if (occurrence->generated && occurrence->paint_box) markers++;
    EXPECT_EQ(markers, 1u);
}

TEST_F(SecondaryViewTest, OverfullLinesOverflowTheirMeasureInsteadOfRejectingTheEdition) {
    init_vector_engine();
    stylesheet("@page { size: 100px 100px; margin: 10px } p { margin: 0; font: 10px/12px Arial; orphans: 1; widows: 1 }");
    DomElement* preformatted = block("WWWWWWWWWWWWWWWW tail", "white-space: pre", "p"); ASSERT_NE(preformatted, nullptr);
    DomElement* centered = block("WWWWWWWWWWWWWWWW tail", "text-align: center", "p"); ASSERT_NE(centered, nullptr);
    ViewTree* tree = secondary(); PagedLayoutOptions options = paged_layout_options_default(); PagedLayoutDiagnostic diagnostic = {};
    ASSERT_EQ(layout_secondary_view(tree, &options, &diagnostic), TYPESET_OK) << diagnostic.reason;
    EXPECT_EQ(tree->model->page_count, 1u);
    // a preserved line never breaks; it keeps every item on one line beyond the 80px measure.
    ViewNodeState* pre = view_tree_node_state(tree, preformatted->first_child, false); ASSERT_NE(pre, nullptr);
    float right = 0.0f;
    for (LayoutViewNode* part = pre->first_occurrence; part; part = part->next_occurrence) {
        EXPECT_FLOAT_EQ(part->rect.y, pre->first_occurrence->rect.y); right = fmaxf(right, part->rect.x + part->rect.width);
    }
    EXPECT_GT(right, 90.0f);
    // the overfull word is start-aligned despite centering, and the following word wraps (CSS Text 3 §6.1).
    ViewNodeState* text = view_tree_node_state(tree, centered->first_child, false); ASSERT_NE(text, nullptr);
    LayoutViewNode* word = nullptr; LayoutViewNode* tail = nullptr;
    // the flow's rect keeps the line's hanging space with the word; the tail starts after it
    for (LayoutViewNode* part = text->first_occurrence; part; part = part->next_occurrence) {
        if (part->text_start == 0 && part->text_length >= 16) word = part;
        if (part->text_start == 17) tail = part;
    }
    ASSERT_NE(word, nullptr); ASSERT_NE(tail, nullptr);
    EXPECT_FLOAT_EQ(word->rect.x, 10.0f); EXPECT_GT(word->rect.width, 80.0f);
    EXPECT_GT(tail->rect.y, word->rect.y); EXPECT_GT(tail->rect.x, 10.0f);
}

TEST_F(SecondaryViewTest, AtomicWrapCrossesSourceOnlyAnchorsAndTrimsNowrapInlineSpaces) {
    init_vector_engine();
    stylesheet("@page { size: 100px 160px; margin: 10px } div { margin: 0; font-size: 10px; line-height: 12px; orphans: 1; widows: 1 }");
    DomElement* body = block(nullptr); ASSERT_NE(body, nullptr);
    DomElement* first = image("width: 50px; height: 10px", body); ASSERT_NE(first, nullptr);
    ASSERT_NE(block(nullptr, "display: none; string-set: Title 'Hidden'", "span", body), nullptr);
    DomElement* second = image("width: 50px; height: 30px", body); ASSERT_NE(second, nullptr);
    DomElement* text = block("A ", "white-space: nowrap", "span", body); ASSERT_NE(text, nullptr);
    DomText* source_text = text->first_child->as_text(); ASSERT_NE(source_text, nullptr);
    DomElement* third = image("width: 80px; height: 10px", body); ASSERT_NE(third, nullptr);
    ViewTree* tree = secondary(); PagedLayoutOptions options = paged_layout_options_default(); PagedLayoutDiagnostic diagnostic = {};
    ASSERT_EQ(layout_secondary_view(tree, &options, &diagnostic), TYPESET_OK) << diagnostic.reason;
    LayoutViewNode* a = source_image_fragment(tree, first), *b = source_image_fragment(tree, second), *c = source_image_fragment(tree, third);
    ASSERT_NE(a, nullptr); ASSERT_NE(b, nullptr); ASSERT_NE(c, nullptr);
    EXPECT_GT(b->rect.y, a->rect.y + 10.0f); EXPECT_GT(c->rect.y, b->rect.y + 30.0f);
    EXPECT_FLOAT_EQ(c->rect.x, 10.0f);
    ViewNodeState* state = view_tree_node_state(tree, source_text, false); ASSERT_NE(state, nullptr);
    StrBuf* content = strbuf_new(); ASSERT_NE(content, nullptr);
    size_t bytes = 0;
    for (LayoutViewNode* node = state->first_occurrence; node; node = node->next_occurrence) {
        EXPECT_EQ(node->text_start, bytes); bytes += node->text_length;
        append_fragment_text(node, content);
    }
    EXPECT_EQ(bytes, source_text->length);
    // text rects retain source separators (§4.5); the consumed gap has no layout width.
    EXPECT_STREQ(content->str, "A "); strbuf_free(content);
    EXPECT_STREQ(source_text->text, "A ");
    LayoutViewNode* painted = source_glyph_text(tree, source_text, "A "); ASSERT_NE(painted, nullptr);
    const FontBox* font = paint_glyph_run_font(painted->glyph_run); ASSERT_NE(font, nullptr);
    EXPECT_NEAR(painted->rect.width, font_measure_char(font_box_handle(font), 'A'), 0.01f);
}

TEST_F(SecondaryViewTest, InlineImagesUseTheBaselineAndClipCoverAndContainInTheirContentBoxes) {
    init_vector_engine();
    stylesheet("@page { size: 220px 150px; margin: 10px } p, div { margin: 0; font-size: 10px; line-height: 12px }");
    DomElement* body = block("Text "); ASSERT_NE(body, nullptr);
    DomElement* cover = image("width: 20px; height: 20px; padding: 2px; border: 1px solid green; object-fit: cover; object-position: right top", body);
    DomElement* contain = image("display: block; width: 40px; height: 40px; object-fit: contain; background: yellow");
    ASSERT_NE(cover, nullptr); ASSERT_NE(contain, nullptr);
    ASSERT_TRUE(create_dir("temp/paged-media-images"));
    ViewTree* tree = secondary(); PagedLayoutOptions options = paged_layout_options_default(); PagedLayoutDiagnostic diagnostic = {};
    ASSERT_EQ(layout_secondary_view(tree, &options, &diagnostic), TYPESET_OK) << diagnostic.reason;
    LayoutViewNode* image = source_image_fragment(tree, cover); ASSERT_NE(image, nullptr);
    LayoutViewNode* text = source_fragment(tree, body->first_child, VIEW_FRAGMENT_BODY, false); ASSERT_NE(text, nullptr);
    ASSERT_NE(text->glyph_run, nullptr);
    EXPECT_FLOAT_EQ(image->rect.width, 26.0f); EXPECT_FLOAT_EQ(image->rect.height, 26.0f);
    EXPECT_FLOAT_EQ(image->rect.y + image->rect.height, text->glyph_run->baseline_y);
    EXPECT_LT(image->image_box->image_rect.x, image->image_box->content_rect.x);
    EXPECT_FLOAT_EQ(image->image_box->image_rect.width, 40.0f);
    LayoutViewNode* contained = source_image_fragment(tree, contain); ASSERT_NE(contained, nullptr);
    EXPECT_FLOAT_EQ(contained->image_box->image_rect.width, 40.0f); EXPECT_FLOAT_EQ(contained->image_box->image_rect.height, 20.0f);
    ImageSurface* snapshot = render_secondary_page_snapshot(tree, 1, 2.0f); ASSERT_NE(snapshot, nullptr);
    Color blue = {snapshot_pixel(snapshot, (size_t)((image->image_box->content_rect.x + 5.0f) * 2.0f), (size_t)((image->image_box->content_rect.y + 5.0f) * 2.0f))};
    EXPECT_GT(blue.b, 200); EXPECT_LT(blue.r, 30);
    Color yellow = {snapshot_pixel(snapshot, (size_t)((contained->rect.x + 5.0f) * 2.0f), (size_t)((contained->rect.y + 5.0f) * 2.0f))};
    EXPECT_GT(yellow.r, 200); EXPECT_GT(yellow.g, 200); EXPECT_LT(yellow.b, 30);
    save_surface_to_png(snapshot, "temp/paged-media-images/image-fit-native.png"); image_surface_destroy(snapshot);
    EXPECT_TRUE(render_secondary_view_to_pdf(tree, "temp/paged-media-images/image-fit.pdf"));
}

TEST_F(SecondaryViewTest, ImageAssetsBelongToEachEditionAndSurviveTheRetainedPageLease) {
    init_vector_engine();
    stylesheet("@page { size: 160px 100px; margin: 10px } p { margin: 0 }");
    DomElement* image = this->image(); ASSERT_NE(image, nullptr);
    ViewTree* a = secondary(), *b = secondary(); ASSERT_NE(a, nullptr); ASSERT_NE(b, nullptr);
    PagedLayoutOptions options = paged_layout_options_default();
    ASSERT_EQ(layout_secondary_view(a, &options, nullptr), TYPESET_OK);
    ASSERT_EQ(layout_secondary_view(b, &options, nullptr), TYPESET_OK);
    LayoutViewNode* first = source_image_fragment(a, image), *second = source_image_fragment(b, image);
    ASSERT_NE(first, nullptr); ASSERT_NE(second, nullptr);
    ImageSurface* old = first->image_box->image; auto handle = old->self;
    EXPECT_NE(old, second->image_box->image.get()); expect_independent_workspace_image(second, image);
    ViewPageSelection all = {true, nullptr, 0}; ViewPreviewOptions preview_options = view_preview_options_default();
    ViewTree* preview = view_tree_page_instances_create(a, &all, &preview_options); ASSERT_NE(preview, nullptr);
    ASSERT_TRUE(view_tree_model_reset(a)); EXPECT_EQ(image_surface_lookup(handle), old);
    ASSERT_EQ(layout_secondary_view(a, &options, nullptr), TYPESET_OK);
    EXPECT_NE(source_image_fragment(a, image)->image_box->image.get(), old);
    ASSERT_TRUE(view_tree_secondary_release(&doc, a)); EXPECT_EQ(image_surface_lookup(handle), old);
    ImageSurface* snapshot = render_secondary_page_snapshot(preview, 1, 2.0f); ASSERT_NE(snapshot, nullptr);
    image_surface_destroy(snapshot);
    ASSERT_TRUE(view_tree_secondary_release(&doc, preview)); EXPECT_EQ(image_surface_lookup(handle), nullptr);
    EXPECT_NE(source_image_fragment(b, image)->image_box->image, nullptr);
}

